css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 10%; background: #0a0f0a; }
.loader span { position: absolute; top: 0; width: 13%; height: 42%; background: linear-gradient(transparent, var(--accent) 62%, color-mix(in srgb, #fff 60%, var(--accent-2))); border-radius: 4px; animation: mrain calc(var(--loader-speed) * 1.6) linear infinite; }
.loader span:nth-child(1) { left: 6%; animation-duration: calc(var(--loader-speed) * 1.4); animation-delay: 0s; }
.loader span:nth-child(2) { left: 26%; animation-duration: calc(var(--loader-speed) * 2); animation-delay: calc(var(--loader-speed) * -.6); }
.loader span:nth-child(3) { left: 46%; animation-duration: calc(var(--loader-speed) * 1.7); animation-delay: calc(var(--loader-speed) * -1); }
.loader span:nth-child(4) { left: 66%; animation-duration: calc(var(--loader-speed) * 2.3); animation-delay: calc(var(--loader-speed) * -.3); }
.loader span:nth-child(5) { left: 84%; animation-duration: calc(var(--loader-speed) * 1.5); animation-delay: calc(var(--loader-speed) * -1.4); }
@keyframes mrain { 0% { transform: translateY(-110%); } 100% { transform: translateY(255%); } }
